package ru.citymonitor.graph.service;

import org.springframework.jdbc.core.*;import org.springframework.stereotype.Service;import ru.citymonitor.graph.dto.GraphDtos.*;
import java.time.*;import java.util.*;import java.util.stream.*;

@Service public class GraphQueryService {
 private final JdbcTemplate db;private final GraphProjectionWriter projection;
 public GraphQueryService(JdbcTemplate db,GraphProjectionWriter projection){this.db=db;this.projection=projection;}
 public GraphView current(String objectId,String edgeType){List<GraphNode> nodes=projection.loadNodes(true).stream().filter(n->objectId==null||objectId.equals(n.objectId())).toList();Set<UUID> ids=nodes.stream().map(GraphNode::factId).collect(Collectors.toSet());List<GraphEdge> edges=projection.loadEdges().stream().filter(e->edgeType==null||edgeType.equals(e.edgeType())).filter(e->objectId==null||ids.contains(e.sourceFactId())||ids.contains(e.targetFactId())).toList();List<VersionSummary> v=versions(0,1);return new GraphView(v.isEmpty()?null:v.get(0).versionId(),v.isEmpty()?null:v.get(0).recordedAt(),projection.lastSequence(),nodes,edges);}
 public ChainView chain(String objectId,LocalDate day){OffsetDateTime end=day.plusDays(1).atStartOfDay().atOffset(ZoneOffset.UTC);List<Long> ids=db.query("select version_id from graph_version where recorded_at < ? order by version_id desc limit 1",(rs,i)->rs.getLong(1),end);if(ids.isEmpty())return new ChainView(objectId,day,null,null,List.of(),List.of());long version=ids.get(0);OffsetDateTime recorded=db.queryForObject("select recorded_at from graph_version where version_id=?",OffsetDateTime.class,version);
  List<GraphNode> nodes=db.query("select fact_id,object_id,occurred_at,event_type,severity,description,sensor_id,latitude,longitude,active,position from graph_node_snapshot where version_id=? and object_id=? and active=true order by position",nodeMapper(),version,objectId);Set<UUID> idsIn=nodes.stream().map(GraphNode::factId).collect(Collectors.toSet());List<GraphEdge> edges=snapshotEdges(version).stream().filter(e->idsIn.contains(e.sourceFactId())||idsIn.contains(e.targetFactId())).toList();return new ChainView(objectId,day,version,recorded,nodes,edges);
 }
 public Lifecycle lifecycle(UUID id){List<GraphNode> found=projection.loadNodes(false).stream().filter(n->n.factId().equals(id)).toList();if(found.isEmpty())throw new NoSuchElementException("Факт не найден в проекции: "+id);GraphNode fact=found.get(0);
  List<LifecycleEvent> events=new ArrayList<>();db.query("select h.position,h.valid_from_version,h.reason,v.recorded_at,v.through_sequence from fact_position_history h join graph_version v on v.version_id=h.valid_from_version where h.fact_id=? order by h.valid_from_version",(rs)->{events.add(new LifecycleEvent("REGISTERED".equals(rs.getString(3))?"REGISTERED":"POSITION_CHANGED",rs.getObject(4,OffsetDateTime.class),rs.getLong(2),rs.getLong(5),rs.getInt(1),rs.getString(3)));},id);
  db.query("select c.version_id,c.source_sequence,c.recorded_at,c.position from graph_change c where c.fact_id=? and c.change_type='NODE_DELETED' order by c.version_id",rs->{events.add(new LifecycleEvent("DELETED",rs.getObject(3,OffsetDateTime.class),rs.getLong(1),rs.getLong(2),(Integer)rs.getObject(4),"LOGICAL_DELETE"));},id);events.sort(Comparator.comparing(LifecycleEvent::recordedAt));return new Lifecycle(id,fact.objectId(),fact.active(),fact.position(),events);
 }
 public List<VersionSummary> versions(int page,int size){return db.query("select version_id,recorded_at,through_sequence,source from graph_version order by version_id desc limit ? offset ?",(rs,i)->new VersionSummary(rs.getLong(1),rs.getObject(2,OffsetDateTime.class),rs.getLong(3),rs.getString(4)),size,page*size);}
 public GraphView version(long id){List<OffsetDateTime> time=db.query("select recorded_at from graph_version where version_id=?",(rs,i)->rs.getObject(1,OffsetDateTime.class),id);if(time.isEmpty())throw new NoSuchElementException("Версия не найдена: "+id);List<GraphNode> nodes=db.query("select fact_id,object_id,occurred_at,event_type,severity,description,sensor_id,latitude,longitude,active,position from graph_node_snapshot where version_id=? and active=true order by object_id,position",nodeMapper(),id);long seq=db.queryForObject("select through_sequence from graph_version where version_id=?",Long.class,id);return new GraphView(id,time.get(0),seq,nodes,snapshotEdges(id));}
 public List<ChangeItem> changes(OffsetDateTime from,OffsetDateTime to,String objectId,int page,int size){String sql="select c.id,c.version_id,c.source_sequence,c.recorded_at,c.change_type,c.fact_id,c.object_id,c.position,c.edge_type,c.related_fact_id from graph_change c where (cast(? as timestamptz) is null or c.recorded_at>=?) and (cast(? as timestamptz) is null or c.recorded_at<=?) and (cast(? as varchar) is null or c.object_id=? or c.fact_id in (select fact_id from graph_fact where object_id=?) or c.related_fact_id in (select fact_id from graph_fact where object_id=?)) order by c.id desc limit ? offset ?";return db.query(sql,(rs,i)->new ChangeItem(rs.getLong(1),rs.getLong(2),rs.getLong(3),rs.getObject(4,OffsetDateTime.class),rs.getString(5),rs.getObject(6,UUID.class),rs.getString(7),(Integer)rs.getObject(8),rs.getString(9),rs.getObject(10,UUID.class)),from,from,to,to,objectId,objectId,objectId,objectId,size,page*size);}
 private List<GraphEdge> snapshotEdges(long version){return db.query("select source_fact_id,target_fact_id,edge_type from graph_edge_snapshot where version_id=?",(rs,i)->new GraphEdge(rs.getObject(1,UUID.class),rs.getObject(2,UUID.class),rs.getString(3)),version);}
 private RowMapper<GraphNode> nodeMapper(){return (rs,i)->new GraphNode(rs.getObject(1,UUID.class),rs.getString(2),rs.getObject(3,OffsetDateTime.class),rs.getString(4),rs.getString(5),rs.getString(6),rs.getString(7),rs.getDouble(8),rs.getDouble(9),rs.getBoolean(10),(Integer)rs.getObject(11));}
}
